import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem69 protege identidade operação e idempotência',()=>{for(const [id,titulo] of [['dgcv2JkW8bL6DBSEqB9V','Strong Creatine 300g - Fisionutri 100% Pure'],['dNFcgW7f0gXpuucpEemY','Case para HD SSD de 2.5" USB 3.0 Transparente da Divanstor']]){const p={id,titulo,preco:'preservado',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,titulo:'Outro produto',comentario:'manter'}).comentario,'manter');assert.doesNotMatch(x.pros,/100%|6 Gbps|garant/i);}});
